import{_ as n,o as i,c as o,a0 as e}from"./chunks/framework.DhQjJcnt.js";const r="/assets/overview-artifact-layers.DwKByzp1.png",c="/assets/overview-ssot-hub.CluFr9k8.png",a="/assets/overview-testing-e2e.D_X3Fifu.png",h="/assets/overview-phase-recalibration.DjSAxLNX.png",s="/assets/phase-cut-mock-ui.DWKhe80z.png",g="/assets/phase-spec-verbal.D1oskYwG.png",l="/assets/phase-no-test-doc.Bz2mCmns.png",d="/assets/phase-api-before-contract.D1lJdKdG.png",u="/assets/phase-no-e2e.CEncqn_L.png",T=JSON.parse('{"title":"Tổng quan","description":"","frontmatter":{},"headers":[],"relativePath":"overview/index.md","filePath":"overview/index.md"}'),p={name:"overview/index.md"};function m(v,t,k,b,f,y){return i(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="tong-quan" tabindex="-1">Tổng quan <a class="header-anchor" href="#tong-quan" aria-label="Permalink to &quot;Tổng quan&quot;">​</a></h1><p>Tài liệu này dành cho member team phát triển phần mềm: giải thích <strong>vì sao</strong> cần bộ artifact đầy đủ và có cấu trúc, <strong>vai trò SSOT</strong> trong dự án, <strong>cách các phase phát triển thường bị cắt giảm</strong> khi đẩy nhanh — và <strong>cách FlowGrid cùng AI hiệu chỉnh</strong> để vẫn giữ lane quan trọng mà không trả lại toàn bộ chi phí viết tài liệu thủ công. Toolkit tối ưu ở chỗ: chuẩn hóa định dạng trên repo, skill và agent bám cùng lane, audit/gate phát hiện thiếu sót có cấu trúc, codegen và sinh testcase/E2E lấp phần <strong>công số</strong> — để team tập trung <strong>grill, review và chốt</strong> thay vì bỏ hẳn tài liệu vì “agile không cần doc”.</p><h2 id="ba-nguyen-tac-van-hanh" tabindex="-1">Ba nguyên tắc vận hành <a class="header-anchor" href="#ba-nguyen-tac-van-hanh" aria-label="Permalink to &quot;Ba nguyên tắc vận hành&quot;">​</a></h2><p>FlowGrid kết hợp <strong>script deterministic</strong> và <strong>agent</strong> trên cùng SSOT — hai lớp bổ trợ, không thay nhau:</p><ol><li><strong>Phân vai kiểm tra (lượng / chất)</strong> — <code>flowgrid audit *</code>, <code>cases:gate</code> báo thiếu field, schema, trace (<code>gaps[]</code>, <code>confirms[]</code>) bằng Node thuần; grill (<code>/grill-bqa</code>, <code>/grill-dev</code>, …) và review member xử lý logic nghiệp vụ, nhất quán UI ↔ API ↔ testcase. Agent bám skill chuẩn (<code>/spec</code>, <code>/legacy</code>, <code>/update-spec</code>, …), không tự điền thiếu sót im lặng — gap phải grill hoặc chốt qua <code>qa/open</code>. Chi tiết: <a href="./../workflows/grill-and-human-review.html">workflows/grill-and-human-review.md</a>.</li><li><strong>Legacy và catalog dùng chung</strong> — brownfield: audit <strong>2 tầng</strong> (màn/API vs luồng cross-flow), <code>/adopt</code> gom candidate <code>CMN-*</code>, codebase mới <strong>không</strong> copy-paste file lẻ từ repo cũ. Chi tiết: <a href="./../workflows/legacy-brownfield.html">workflows/legacy-brownfield.md</a>.</li><li><strong>Kỷ luật workflow</strong> — khi <code>gaps[]</code> + <code>confirms[]</code> vượt ngưỡng (~10), dừng hỏi lẻ, chuyển plan chia phase (Law 2); spec màn lớn phân <strong>zone</strong> (header, toolbar, bảng/form, footer) từng lượt để tránh lost-in-the-middle; <code>audit</code>/<code>gate</code> chạy sau artifact, <strong>không</strong> thay backlog hay sprint board. Mốc gate: <a href="./../workflows/gates.html">workflows/gates.md</a> · chuỗi đóng một function (<code>W-*</code>): <a href="./../workflows/gates.html#close-one-function">gates § Đóng một function</a>.</li></ol><p>Đội <strong>T-shaped</strong> dùng FlowGrid làm lane artifact trên một function (<code>W-*</code>): spec → prototype → API → tests-docs → wire — macro và vai trò: <a href="./../workflows/">workflows/index.md</a>.</p><h2 id="ba-ngu-canh-trien-khai" tabindex="-1">Ba ngữ cảnh triển khai <a class="header-anchor" href="#ba-ngu-canh-trien-khai" aria-label="Permalink to &quot;Ba ngữ cảnh triển khai&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ngữ cảnh</th><th>Đặc điểm</th><th>Lane gợi ý</th></tr></thead><tbody><tr><td><strong>Greenfield</strong></td><td>Dự án mới, stack chuẩn adapter</td><td><code>/architecture</code> → <code>/overview</code>, <code>/module</code>, <code>/spec</code> → audit spec (<code>--type</code>) → prototype → testcase/E2E</td></tr><tr><td><strong>Modernization / re-platform</strong></td><td>Code cũ làm nguồn, hệ mới cần catalog</td><td><code>/adopt</code>, <code>/legacy /spec</code>, 2-tier audit; tái dùng <code>CMN-*</code> thay nhân bản màn</td></tr><tr><td><strong>Maintain / base tùy biến</strong></td><td>UI library hoặc kiến trúc lệch template mặc định</td><td><code>flowgrid init</code> <strong>Custom</strong> + Golden Sample → <code>build-template-code</code> → spec/gen trên registry/lexicon đã học</td></tr></tbody></table><h2 id="cac-lop-artifact-mot-team-can" tabindex="-1">Các lớp artifact một team cần <a class="header-anchor" href="#cac-lop-artifact-mot-team-can" aria-label="Permalink to &quot;Các lớp artifact một team cần&quot;">​</a></h2><p><img src="'+r+'" alt="Các lớp artifact song song với code"></p><p>Một sản phẩm phần mềm “đủ nghiệp vụ” thường phải duy trì nhiều lớp đầu ra song song với code. Khi deadline gấp, các lớp này hay bị <strong>cắt</strong> hoặc <strong>viết sơ</strong> — tiết kiệm ngắn hạn, đổi lại mơ hồ, onboarding chậm, lệch FE–BE và regression mỗi release. Agile đúng nghĩa ưu tiên <strong>trao đổi</strong> để hiểu đúng bài toán; sau khi chốt, vẫn cần <strong>ghi nhận</strong> để lane sau (dev khác, QA, agent) không phải đoán.</p><ul><li><strong>Yêu cầu &amp; phạm vi</strong><ul><li>vision, mục tiêu, actor/persona;</li><li>phạm vi release, giả định, quyết định kiến trúc/sản phẩm.</li></ul></li><li><strong>Spec chức năng</strong><ul><li>user story, acceptance;</li><li>luồng màn hình, rule nghiệp vụ;</li><li>open question (QA) chờ làm rõ.</li></ul></li><li><strong>Thiết kế trải nghiệm</strong><ul><li>wireframe, mock, prototype;</li><li>thống nhất hành vi trước khi “đóng” UI production.</li></ul></li><li><strong>Hợp đồng kỹ thuật</strong><ul><li>API, schema, integration;</li><li>data và gọi dịch vụ ngoài — FE, BE và hệ thống bên thứ ba cùng một bản chốt.</li></ul></li><li><strong>Kiểm thử</strong><ul><li>testcase, scenario, test suite;</li><li>làm căn cho test thủ công và automation.</li></ul></li><li><strong>Vận hành &amp; chất lượng</strong><ul><li>technical debt, derived requirement;</li><li>ghi nhận phụ thuộc ngoài, ràng buộc vận hành, marker cập nhật sau release.</li></ul></li></ul><p>FlowGrid không thay thế việc team <strong>chọn phạm vi</strong> theo quy mô dự án; nó giúp khi đã chọn ghi nhận thì ghi <strong>đúng chỗ, đúng format</strong>, và duy trì <strong>nhẹ</strong> nhờ AI hỗ trợ draft — member vẫn review và chốt.</p><h2 id="ssot-—-vai-tro-trung-tam" tabindex="-1">SSOT — vai trò trung tâm <a class="header-anchor" href="#ssot-—-vai-tro-trung-tam" aria-label="Permalink to &quot;SSOT — vai trò trung tâm&quot;">​</a></h2><p><img src="'+c+'" alt="SSOT — một nguồn chốt, nhiều lane đọc cùng artifact"></p><p><strong>Single Source of Truth (SSOT)</strong> trong FlowGrid là <strong>artifact trên disk</strong> (docs-hub, tests-docs, contract trong repo code) được <code>flowgrid init</code> trỏ rõ — <strong>cùng version control với code</strong>, không phải slide rời hoặc wiki tách repo không đồng bộ merge.</p><p>SSOT đóng các vai trò sau cho cả dự án:</p><ul><li><strong>Nguồn tin chính xác nhất</strong> cho một chủ đề đã chốt: spec chức năng, ma trận testcase, API contract, business-process curated vs detail — mọi lane (BA, dev FE/BE, QA, agent) đọc <strong>cùng file</strong>, không mỗi người một bản Excel hoặc thread chat làm “bản chính”.</li><li><strong>Trọng tài khi tranh luận:</strong> hai cách hiểu khác nhau về hành vi màn hình, field API hay coverage test → so với SSOT (bundle, <code>TC-*.yaml</code>, <code>01-backend-spec.yaml</code>, …). Quyết định thay đổi phải <strong>cập nhật artifact</strong>; grill và audit giúp phát hiện chỗ chưa khớp trước khi merge code.</li><li><strong>Khóa write rule — tránh nhân bản mâu thuẫn:</strong> ví dụ business-process — tầng Architecture giữ overview <code>FLOW-*</code> sơ, curated; chi tiết actor/action/exception nằm Common theo scope. Module <code>CMP-*</code> có <strong>owner surface</strong>; surface khác <strong>map/link</strong>, không copy SSOT. Function là leaf <code>W-*</code> / <code>API-*</code> với bundle + IR + API seq. Vi phạm rule → codegen, portal và agent dễ <strong>lệch</strong> spec thật.</li><li><strong>Một địa chỉ cho agent:</strong> slash skill và MCP đọc path cố định; prompt không phải mô tả lại cấu trúc dự án mỗi phiên. SSOT là “bản đồ” mà harness và engine audit cùng tin.</li><li><strong>Điều kiện cho kiểm định máy:</strong> <code>flowgrid audit *</code>, <code>cases:gate</code> so schema, field bắt buộc, trace testcase ↔ bundle — chỉ có ý nghĩa khi đã có <strong>định dạng chuẩn</strong> và một nơi chốt. Audit báo <strong>lượng</strong> (thiếu, lệch cấu trúc); grill nghiệp vụ và review release vẫn là <strong>chất</strong> — do member và lead.</li></ul><p>SSOT <strong>không</strong> bắt buộc viết dài. SSOT có nghĩa <strong>đủ field, đủ liên kết</strong>, cập nhật khi đổi scope — AI sinh bản đầu và gợi ý patch; người giữ đúng nghiệp vụ và quyết định sản phẩm. Triết lý toolkit: <strong>cung cấp SSOT, skill, audit/gate và đường gen E2E</strong>; team <strong>chọn chạy đúng luồng</strong>, đọc gap, và <strong>chốt</strong>.</p><h2 id="kiem-thu-thu-cong-it-va-automation-e2e" tabindex="-1">Kiểm thử thủ công, IT và automation E2E <a class="header-anchor" href="#kiem-thu-thu-cong-it-va-automation-e2e" aria-label="Permalink to &quot;Kiểm thử thủ công, IT và automation E2E&quot;">​</a></h2><p><img src="'+a+'" alt="Từ tests-docs đến automation E2E — giảm IT lặp"></p><p>Regression thủ công trước release — nhất là sản phẩm nhiều màn hình — tốn người, dễ sót, khó đảm bảo cùng một độ phủ giữa các lần phát hành. Manual và exploratory vẫn cần cho ngữ cảnh mới; điểm đau là <strong>lặp lại</strong> cùng bộ kiểm tra đã biết.</p><p>Luồng khớp SSOT:</p><ul><li><strong>Testcase và scenario</strong> là hub tại <strong>tests-docs</strong> (tách với repo chạy Playwright nếu cần).</li><li>AI hỗ trợ sinh và mở rộng ma trận; QA <strong>grill</strong> nghiệp vụ và trace về bundle/spec.</li><li><strong>Automation E2E</strong> sinh từ document testcase; dev bổ sung lỗ hổng kỹ thuật còn thiếu.</li><li>Trước release: chạy automation và đối chiếu doc ↔ spec E2E (audit e2e) để giảm lệch giữa “đã viết” và “đã chạy”.</li></ul><p>Member QA chỉ có kỹ năng manual vẫn có thể nhờ AI gen lane automation; <strong>không</strong> thay policy release một vòng manual khi team vẫn yêu cầu — toolkit <strong>hỗ trợ</strong> giảm gánh IT lặp.</p><h2 id="phase-phat-trien-va-hieu-chinh-khi-đi-nhanh" tabindex="-1">Phase phát triển và hiệu chỉnh khi đi nhanh <a class="header-anchor" href="#phase-phat-trien-va-hieu-chinh-khi-đi-nhanh" aria-label="Permalink to &quot;Phase phát triển và hiệu chỉnh khi đi nhanh&quot;">​</a></h2><p><img src="'+h+'" alt="Cắt phase khi đi nhanh vs hiệu chỉnh prototype — spec — wire"></p><p>Nhiều mô hình (spiral, dual-track, v.v.) đều có các <strong>mốc tương đương</strong>: khám phá &amp; phạm vi → thiết kế chi tiết (UX, spec) → xây dựng FE/BE → kiểm thử → tích hợp &amp; phát hành. Team tốc độ cao thường <strong>gộp hoặc bỏ</strong> bước để giảm chi phí. FlowGrid <strong>không</strong> ép waterfall đầy đủ; nó <strong>giữ phase quan trọng</strong> dưới dạng artifact + skill + gate, và <strong>rút thời gian</strong> nhờ prototype nhanh, spec có schema, AI/codegen — macro <strong>design → code + test → wire</strong> là cách gom các mốc trên cho một nhịp release.</p><h3 id="cat-mock-design-ui" tabindex="-1">Cắt mock / design UI <a class="header-anchor" href="#cat-mock-design-ui" aria-label="Permalink to &quot;Cắt mock / design UI&quot;">​</a></h3><p><img src="'+s+'" alt="Chắp vá production vs prototype sớm — stakeholder thử hành vi trước khi code cứng"></p><ul><li><strong>Rủi ro</strong><ul><li>UI lệch kỳ vọng stakeholder so với hình dung ban đầu.</li><li>Rework nhiều trên code production đã “đóng” layout và component.</li><li>Đến cuối sprint mới thấy thiếu sót nhưng không muốn rework lớn → <strong>chắp vá</strong> cho kịp release.</li><li>Không có <strong>design kỹ thuật</strong> (state, action, field, error path) chuẩn từ đầu → dev và QA tự suy diễn khác nhau.</li></ul></li><li><strong>Hiệu chỉnh</strong><ul><li>Thay vì bỏ hẳn lane thiết kế hoặc vẽ tĩnh dài rồi sửa nhiều vòng: <strong>prototype / mock sớm nhất, nhanh nhất</strong> có thể.</li><li>Từ yêu cầu cơ bản, gạch đầu dòng team/stakeholder bàn bạc — <strong>build màn hình prototype</strong> để họ trải nghiệm sớm (AI + skill <code>/prototype</code> hỗ trợ lane này).</li><li><strong>Lấy feedback sớm</strong>, sửa trên prototype rẻ hơn sửa trên production.</li><li>Sau khi <strong>chốt prototype</strong> → chốt <strong>SSOT spec</strong> trên docs-hub → design kỹ thuật (bundle/IR) → viết / cập nhật testcase — không nhảy thẳng code cứng khi hành vi chưa ổn.</li></ul></li></ul><h3 id="spec-chi-trao-đoi-mieng" tabindex="-1">Spec chỉ trao đổi miệng <a class="header-anchor" href="#spec-chi-trao-đoi-mieng" aria-label="Permalink to &quot;Spec chỉ trao đổi miệng&quot;">​</a></h3><p><img src="'+g+'" alt="Sương mù trao đổi miệng vs một bản spec SSOT nối cả team và agent"></p><ul><li><strong>Rủi ro</strong><ul><li>Dev, QA và stakeholder nhớ <strong>khác phiên</strong> — không có bản “đã chốt” để đối chiếu.</li><li>Agent sinh code/patch <strong>sai ngữ cảnh</strong> vì prompt không bám artifact.</li><li>Onboard member mới hoặc handoff giữa sprint <strong>tốn thời gian</strong> hỏi lại từ đầu.</li><li>CR giữa chừng không ai biết <strong>delta</strong> so với bản trước — dễ sót rule nghiệp vụ.</li></ul></li><li><strong>Hiệu chỉnh</strong><ul><li>Sau trao đổi: capture vào <strong>spec có schema</strong> trên docs-hub (user story, rule, open question) — ngắn nhưng <strong>đủ field</strong>.</li><li>AI draft từ meeting note hoặc bullet; BA/dev <strong>grill</strong> trước codegen.</li><li>Mỗi thay đổi scope đáng kể → <code>/update-spec</code> (hoặc tương đương) + re-audit — SSOT luôn là trọng tài.</li><li>Chat và meeting giữ vai trò <strong>khám phá</strong>; SSOT giữ vai trò <strong>đã quyết</strong>.</li></ul></li></ul><h3 id="khong-document-testcase" tabindex="-1">Không document testcase <a class="header-anchor" href="#khong-document-testcase" aria-label="Permalink to &quot;Không document testcase&quot;">​</a></h3><p><img src="'+l+'" alt="Vòng IT thủ công lặp vs hub tests-docs nuôi automation"></p><ul><li><strong>Rủi ro</strong><ul><li><strong>IT thủ công</strong> lặp cùng checklist mỗi release — tốn người, dễ sót case đã biết.</li><li>Regression không <strong>trace</strong> về requirement — không biết bug “đã được spec chưa”.</li><li>QA và dev test <strong>khác bộ</strong> — báo pass nhưng production vẫn lỗi lane khác.</li><li>Không có căn để sinh automation — mỗi lần phải viết tay từ đầu.</li></ul></li><li><strong>Hiệu chỉnh</strong><ul><li>Duy trì <strong>tests-docs</strong>: scenario, ma trận <code>TC-*.yaml</code>, suite có traceability về bundle.</li><li>AI hỗ trợ sinh / mở rộng ma trận; QA grill <strong>chất</strong> nghiệp vụ.</li><li><strong><code>cases:gate</code></strong> trước khi coi testcase “đóng” cho scope — giảm merge “cho có”.</li><li>Document testcase là <strong>đầu vào</strong> cho E2E (mục kiểm thử phía trên), không tách rời spec đã chốt.</li></ul></li></ul><h3 id="code-api-truoc-contract" tabindex="-1">Code API trước contract <a class="header-anchor" href="#code-api-truoc-contract" aria-label="Permalink to &quot;Code API trước contract&quot;">​</a></h3><p><img src="'+d+'" alt="FE–BE lệch ở wire vs contract SSOT là cầu nối tích hợp"></p><ul><li><strong>Rủi ro</strong><ul><li>FE gọi field/endpoint <strong>khác</strong> BE thực tế — phát hiện muộn ở wire hoặc UAT.</li><li>Integration với dịch vụ ngoài <strong>đoán</strong> schema — retry và hotfix tốn kém.</li><li>Refactor API sau khi UI đã bind — <strong>breaking</strong> nhiều màn hình.</li><li>Agent gen FE/BE <strong>song song</strong> không có SSOT contract → hai nhánh drift.</li></ul></li><li><strong>Hiệu chỉnh</strong><ul><li><strong>API SSOT</strong> trên artifact (vd. <code>01-backend-spec.yaml</code> theo seq) trước hoặc song song codegen có audit.</li><li>Lane <strong>api-spec</strong> / grill API; align FE–BE bằng <code>audit fe-be</code>, <code>audit api</code>.</li><li>Wire phase là <strong>tích hợp có căn</strong>, không phải lần đầu “mới biết contract sai”.</li><li>Thay đổi contract → cập nhật SSOT trước merge code tiêu thụ.</li></ul></li></ul><h3 id="bo-automation-e2e" tabindex="-1">Bỏ automation E2E <a class="header-anchor" href="#bo-automation-e2e" aria-label="Permalink to &quot;Bỏ automation E2E&quot;">​</a></h3><p><img src="'+u+'" alt="Mệt mỏi regression tay vs luồng testcase sinh E2E chạy ổn định"></p><ul><li><strong>Rủi ro</strong><ul><li><strong>“Đau IT”</strong> mỗi release — cùng luồng critical path phải click lại từ đầu.</li><li>Độ phủ <strong>không ổn định</strong> giữa các phiên (người khác nhau, tâm trạng khác nhau).</li><li>Bug regression <strong>lọt</strong> dù manual đã “test rồi” — không có bộ chạy lặp determinism.</li><li>Team trì hoãn automation vì “không có thời gian viết” — vòng xoắn chi phí IT.</li></ul></li><li><strong>Hiệu chỉnh</strong><ul><li>Testcase document là SSOT; sinh <strong>Playwright</strong> (hoặc stack E2E đã chọn) trên <strong>e2e-root</strong>.</li><li>Dev review phần kỹ thuật, selector, ổn định CI; QA giữ assert nghiệp vụ và ma trận.</li><li>Chạy automation ở pipeline hoặc trước release; <strong>audit e2e</strong> đối chiếu doc ↔ spec đã gen.</li><li>Manual/exploratory giữ cho case mới; automation giảm <strong>lặp</strong> case đã chốt trong tests-docs.</li></ul></li></ul><h2 id="tom-tat" tabindex="-1">Tóm tắt <a class="header-anchor" href="#tom-tat" aria-label="Permalink to &quot;Tóm tắt&quot;">​</a></h2><ul><li><strong>Bài toán gốc</strong><ul><li>Team cần nhiều lớp artifact (phạm vi, spec, UX, contract, test, chất lượng).</li><li>Đẩy nhanh → hay cắt doc hoặc viết sơ → chi phí ẩn: hiểu lệch, onboard chậm, regression.</li><li>Agile nhấn trao đổi; sau chốt vẫn cần capture có cấu trúc.</li></ul></li><li><strong>SSOT</strong><ul><li>Artifact trên repo là nguồn tin chính, trọng tài conflict, khóa write rule, nền cho agent và audit.</li><li>Không đồng nghĩa văn phong dài; đủ field, đủ link, cập nhật khi đổi scope.</li></ul></li><li><strong>Kiểm thử</strong><ul><li>tests-docs là căn testcase; e2e-root chạy automation bám document.</li><li>Giảm IT lặp mỗi release; manual vẫn cho exploratory và policy team.</li></ul></li><li><strong>Phase</strong><ul><li>Có thể cắt phase nhưng không nên xóa hẳn ý nghĩa — thay bằng prototype nhanh, spec schema, gate, contract, E2E.</li><li>Macro design → code + test → wire gom nhịp làm việc thực tế; checklist audit từng leaf: <a href="./../workflows/gates.html#close-one-function">gates § Đóng một function</a>.</li></ul></li><li><strong>Tối ưu FlowGrid + AI</strong><ul><li>AI + skill + codegen lấp <strong>công số</strong> tạo và duy trì artifact.</li><li>Member <strong>grill, review, chốt</strong> — không gom cả repo một lần, không thay quyết định product owner.</li><li>Audit/gate báo thiếu/lệch có cấu trúc; giảm “tin miệng” ở mốc chuyển phase.</li></ul></li></ul><p>Cài đặt CLI, <code>flowgrid init</code>, bảng phase · skill và mô tả harness: xem <strong>README</strong> ở root repository FlowGrid.</p>',46)])])}const S=n(p,[["render",m]]);export{T as __pageData,S as default};
